pages.usage:
import { Badge } from '@tmt/browser-ui/ui';

<Badge>spec</Badge>
<Badge variant="destructive">✕ Blocked</Badge>

import { BlockDocument, Block, BlockHandle, BlockDropLine, BlockGhost, blockKeyAction } from '@tmt/browser-ui/blocks';

<BlockDocument>
  <Block label="Table: Ticket status" kind="table" selected={selected} tabIndex={-1}
    onKeyDown={(event) => run(blockKeyAction(event, selecting))}>
    {hovered && <BlockHandle onInsert={openInsert} onMenu={openMenu} onGripPointerDown={startDrag} />}
    <TableBlock … />
  </Block>
</BlockDocument>
// While dragging: the dragged block takes state="dragging", BlockDropLine marks the landing place
// and BlockGhost follows the pointer.

import { Button } from '@tmt/browser-ui/ui';

<Button type="button">Send</Button>
<Button type="button" variant="outline">New timer</Button>

import { Chips, Chip, Combobox, useLayerController } from '@tmt/browser-ui/ui';

const controller = useLayerController({ open, onOpenChange: setOpen });
<Chips controller={controller} label="Recipients" items={items} options={options}
  query={query} onQueryChange={setQuery} onAdd={add} onRemove={remove} emptyLabel="No member matches" />

import { DataTable } from '@tmt/browser-ui/data-table';

<DataTable label="Pages" rows={pages} rowKey={(page) => page.id} rowLabel={(page) => page.title}
  columns={[{ id: 'title', header: 'Title', role: 'primary', min: 220, text: (page) => page.title, sub: progress },
    { id: 'updated', header: 'Updated', role: 'time', min: 88, max: 104, sortable: true, text: (page) => page.updated }]}
  sort={sort} onSortChange={setSort} selected={selected} onSelectedChange={setSelected}
  actions={(page) => [{ id: 'pin', label: `Pin ${page.title}`, icon: <Pin />, onSelect: pin }]} menu={rowMenu} onOpen={openPage} />

import { ImageBlock } from '@tmt/browser-ui/blocks';
import '@tmt/browser-ui/blocks.css';

<ImageBlock images={images} layout="carousel" />

import { MarkedText } from '@tmt/browser-ui/blocks';
import '@tmt/browser-ui/blocks.css';

<MarkedText text={text} marks={marks} onLink={openLink} />

import { MockupBlock } from '@tmt/browser-ui/blocks';
import '@tmt/browser-ui/blocks.css';

<MockupBlock system="tmt-gui" version="follow">…</MockupBlock>

import { PageView } from '@tmt/browser-ui/blocks';
import '@tmt/browser-ui/blocks.css';

<PageView title="Spec pages" rows={pages} />
<PageView title="Snapshot" rows={authoredPageViewRows(props.rows, { sort: 'title' })} />

import { QuestionBlock } from '@tmt/browser-ui/blocks';
import '@tmt/browser-ui/blocks.css';

<QuestionBlock title="Which screen first?" agent="gui-lead" choices={['Insert', 'Handle']} onSend={sendAnswer} />

import { RichInput, emptyRichInputValue } from '@tmt/browser-ui/rich-input';

<RichInput shape="multi" label="Message" value={value} onChange={setValue} onSubmit={send}
  suggestions={[{ kind: 'mention', trigger: '@', options: (query) => … }]} />

import { WorkBundle } from '@tmt/browser-ui/blocks';
import '@tmt/browser-ui/blocks.css';

<WorkBundle page="page-id" data={page} work="Start with the phone drawer." />
